#include "rinkfit/joint_packet.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("usage: joint_legacy_verify ORIGINAL_EVENT_MODEL JOINT_MODEL JOINT_PACKET REPORT");auto old=rinkfit::EventModel::load(argv[1]);auto model=rinkfit::JointEventModel::load(argv[2]);auto packet=rinkfit::JointPacket::load(argv[3],model);std::vector<rinkfit::Vec2<double>>eo(packet.rows.size()),en(packet.rows.size());std::vector<std::uint8_t>included(packet.rows.size());double maxdiff=0,rsmax=0;std::size_t count=0,invalid=0;for(std::size_t i=0;i<packet.rows.size();++i){const auto&r=packet.rows[i];if(!r.active||r.shot_id!="s01")continue;auto ol=old.layout(r.material,r.path,(r.pts-256256)/12800.);auto op=old.pointers(ol);auto nl=model.layout(model.shot_map.at("s01"),r.material,r.path,r.pts);auto np=model.pointers(nl);auto a=old.predict_explicit(ol,r.station,r.row,op.data());auto b=model.predict_explicit(nl,r.station,r.row,np.data());if(!a.valid()||!b.valid()){++invalid;continue;}included[i]=1;++count;maxdiff=std::max(maxdiff,std::hypot(a.uv[0]-b.uv[0],a.uv[1]-b.uv[1]));rsmax=std::max(rsmax,std::max(std::abs(r.row-a.uv[1]),std::abs(r.row-b.uv[1])));eo[i]={a.uv[0]-r.uv[0],a.uv[1]-r.uv[1]};en[i]={b.uv[0]-r.uv[0],b.uv[1]-r.uv[1]};}double wo=0,wn=0;std::size_t rank=0;for(const auto&g:packet.groups){bool use=true;for(auto i:g.rows)use=use&&included[i];if(!use)continue;rank+=g.rank;for(std::size_t a=0;a<g.rank;++a){double x=0,y=0;for(std::size_t j=0;j<g.rows.size();++j)for(int c=0;c<2;++c){double w=g.W[a*2*g.rows.size()+2*j+c];x+=w*eo[g.rows[j]][c];y+=w*en[g.rows[j]][c];}wo+=.5*x*x;wn+=.5*y*y;}}rinkfit::eventio::Json report={{"schema","rinkfit.joint_latest_s01_same_arithmetic_replay.v1"},{"latest_event_model_sha256",rinkfit::eventio::file_sha256(argv[1])},{"joint_model_sha256",rinkfit::eventio::file_sha256(argv[2])},{"packet_sha256",rinkfit::eventio::file_sha256(argv[3])},{"active_s01_rows",count},{"invalid_rows",invalid},{"original_W_rank",rank},{"max_legacy_joint_UV_difference_px",maxdiff},{"stored_RS_equality_max_px",rsmax},{"legacy_CPP_full_W_half_cost",wo},{"joint_CPP_full_W_half_cost",wn},{"full_W_difference",wn-wo},{"full_ordinary_and_profile_same_imported_nuisance",true},{"passed",invalid==0&&maxdiff<1e-9&&std::abs(wn-wo)<1e-6}};std::ofstream f(argv[4]);f<<report.dump(2);std::cout<<report.dump(2);return report["passed"].get<bool>()?0:2;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
